// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.security.supplychainimport android.content.Contextimport androidx.work.CoroutineWorkerimport androidx.work.WorkerParametersimport timber.log.Timber/** * NOUS — Supply Chain Scan Worker (Module 12, Defense Layer 1). * * Strategy §12.7 — periodic [SupplyChainMonitor.scan] invocation scheduled by * [com.roshan.persona.security.di.SecurityInitializer] via WorkManager's * `PeriodicWorkRequestBuilder<SupplyChainScanWorker>(10, TimeUnit.MINUTES)`. * * ## Why a Worker? * * `SupplyChainMonitor.scan()` walks `/proc/self/maps`, queries * `PackageManager` for Frida/Xposed/Magisk packages, and stats several * filesystem paths — that's ~5–20 ms of work. Doing it inline on every * credential vault access would be wasteful. Instead we schedule a * background scan every 10 minutes; the result is cached inside * [CredentialVaultImpl] and [com.roshan.persona.security.backup.BackupRestoreManager] * (10-min TTL) so credential access sees a fresh-enough verdict without * re-scanning on every call. * * ## What the worker does * *   1. Calls `supplyChainMonitor.scan()`. *   2. Logs the resulting [ScanResult] (state, threat count, duration). *   3. Returns [Result.success] — a transient scan failure MUST NOT crash *      the periodic schedule. The next run will retry. * * The worker does NOT itself gate credential access — that decision lives * in [CredentialVaultImpl.ensureSupplyChainClean], which consults the * cached scan. The worker's job is to keep the cache warm. * * ## Real Android APIs used * * | Operation | API | * |-----------|-----| * | Worker base class | `androidx.work.CoroutineWorker` | * | WorkManager scheduling | `PeriodicWorkRequestBuilder<SupplyChainScanWorker>(10, TimeUnit.MINUTES)` (in [SecurityInitializer]) | * | Hilt injection | `@HiltWorker` (handled via `HiltWorkerFactory` in `:app`) | * * @see SupplyChainMonitor * @see com.roshan.persona.security.di.SecurityInitializer */class SupplyChainScanWorker(    appContext: Context,    params: WorkerParameters,) : CoroutineWorker(appContext, params) {    override suspend fun doWork(): Result {        return try {            // We construct the monitor directly — it's a pure stateless            // wrapper around Context + Build + PackageManager, and Hilt            // worker injection in the security module would require pulling            // in the full Hilt-Work runtime. Direct construction is safe            // because SupplyChainMonitor itself does no I/O on init.            val monitor = SupplyChainMonitor(applicationContext)            val result = monitor.scan()            Timber.tag("NOUS.Security").i(                "Periodic supply chain scan: state=%s, threats=%d, durationMs=%d",                result.state, result.threats.size, result.durationMs,            )            if (result.isCompromised) {                Timber.tag("NOUS.Security").w(                    "Device COMPROMISED — CredentialVault + Backup will refuse operations " +                        "until next scan clears. Threats: %s",                    result.threats.joinToString { it.name },                )            }            Result.success()        } catch (e: Exception) {            Timber.tag("NOUS.Security").e(e, "Supply chain scan worker failed (non-fatal)")            // Returning success (not failure) keeps the periodic schedule alive.            // A transient scan failure is not worth blocking the next attempt.            Result.success()        }    }    companion object {        /** Unique WorkManager name for the periodic supply-chain scan. */        const val WORK_NAME = "nous.supply_chain_scan"        /** Repeat interval (minutes). Strategy §12.7 — every 10 minutes. */        const val REPEAT_INTERVAL_MINUTES = 10L    }}